/**
 * Query Hook Consistency Property Tests
 * 
 * Property-based tests to validate that query hooks generated by the factory
 * follow consistent patterns for fetching, filtering, and pagination across
 * all entity types.
 * 
 * @fileoverview Query hook consistency property tests
 * @version 1.0.0
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import fc from 'fast-check';
import React from 'react';
import { createQueryFactory } from './createQueryFactory';
import { BaseEntity, QueryFilters } from './types/core';
import { QueryFactoryOptions } from './types/query';

// Mock dependencies
vi.mock('@/integrations/supabase/client', () => ({
  supabase: {
    from: vi.fn(() => ({
      select: vi.fn(() => ({
        eq: vi.fn(() => ({
          single: vi.fn(() => Promise.resolve({ 
            data: { id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }, 
            error: null 
          })),
          range: vi.fn(() => Promise.resolve({ 
            data: [{ id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }], 
            error: null, 
            count: 1 
          })),
          order: vi.fn(() => ({
            eq: vi.fn(() => ({
              single: vi.fn(() => Promise.resolve({ 
                data: { id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }, 
                error: null 
              }))
            }))
          }))
        })),
        range: vi.fn(() => Promise.resolve({ 
          data: [{ id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }], 
          error: null, 
          count: 1 
        })),
        order: vi.fn(() => ({
          eq: vi.fn(() => ({
            single: vi.fn(() => Promise.resolve({ 
              data: { id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }, 
              error: null 
            }))
          })),
          range: vi.fn(() => Promise.resolve({ 
            data: [{ id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }], 
            error: null, 
            count: 1 
          }))
        })),
        in: vi.fn(() => ({
          order: vi.fn(() => ({
            range: vi.fn(() => Promise.resolve({ 
              data: [{ id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }], 
              error: null, 
              count: 1 
            }))
          }))
        })),
        like: vi.fn(() => ({
          order: vi.fn(() => ({
            range: vi.fn(() => Promise.resolve({ 
              data: [{ id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }], 
              error: null, 
              count: 1 
            }))
          }))
        })),
        or: vi.fn(() => ({
          order: vi.fn(() => ({
            range: vi.fn(() => Promise.resolve({ 
              data: [{ id: 'test-id', name: 'Test Entity', created_at: '2023-01-01T00:00:00Z', updated_at: '2023-01-01T00:00:00Z' }], 
              error: null, 
              count: 1 
            }))
          }))
        }))
      }))
    })),
    channel: vi.fn(() => ({
      on: vi.fn(() => ({
        subscribe: vi.fn()
      }))
    })),
    removeChannel: vi.fn()
  }
}));

vi.mock('@/contexts/AuthContext', () => ({
  useAuth: vi.fn(() => ({
    business: { id: 'test-business-id' }
  }))
}));

// Test entity interfaces
interface TestCustomer extends BaseEntity {
  name: string;
  email?: string;
  phone?: string;
}

interface TestProduct extends BaseEntity {
  name: string;
  price: number;
  category?: string;
}

interface TestLead extends BaseEntity {
  name: string;
  email?: string;
  status: string;
}

// Test wrapper component
const createWrapper = () => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false },
      mutations: { retry: false }
    }
  });
  
  // eslint-disable-next-line react/display-name
  return ({ children }: { children: React.ReactNode }) => {
    return React.createElement(QueryClientProvider, { client: queryClient }, children);
  };
};

// Custom arbitraries for query factory testing
const Arbitraries = {
  tableName: (): fc.Arbitrary<string> =>
    fc.constantFrom('customers', 'products', 'leads', 'sales', 'orders', 'users'),

  queryFilters: (): fc.Arbitrary<QueryFilters> =>
    fc.record({
      where: fc.option(fc.dictionary(
        fc.string({ minLength: 1, maxLength: 20 }),
        fc.oneof(
          fc.string(),
          fc.integer(),
          fc.boolean(),
          fc.array(fc.string(), { minLength: 1, maxLength: 5 })
        )
      )),
      search: fc.option(fc.string({ minLength: 1, maxLength: 50 })),
      searchFields: fc.option(fc.array(fc.string({ minLength: 1, maxLength: 20 }), { minLength: 1, maxLength: 5 })),
      orderBy: fc.option(fc.record({
        field: fc.string({ minLength: 1, maxLength: 20 }),
        direction: fc.constantFrom('asc', 'desc')
      }))
    }),

  queryFactoryOptions: (): fc.Arbitrary<QueryFactoryOptions> =>
    fc.record({
      tableName: Arbitraries.tableName(),
      defaultFilters: fc.option(Arbitraries.queryFilters()),
      realTimeSubscription: fc.option(fc.boolean()),
      cacheTime: fc.option(fc.integer({ min: 1000, max: 600000 })),
      staleTime: fc.option(fc.integer({ min: 0, max: 300000 })),
      defaultPageSize: fc.option(fc.integer({ min: 5, max: 100 })),
      select: fc.option(fc.string({ minLength: 1, maxLength: 100 })),
      joins: fc.option(fc.array(fc.string({ minLength: 1, maxLength: 20 }), { maxLength: 3 }))
    }),

  entityId: (): fc.Arbitrary<string> =>
    fc.string({ minLength: 1, maxLength: 50 })
};

/**
 * Property-Based Tests for Query Hook Consistency
 * **Property 6: Query Hook Pattern Consistency**
 * **Validates: Requirements 2.1**
 */
describe('Query Hook Consistency Property Tests', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Property 6: Query Hook Pattern Consistency', () => {
    it('should generate hooks with consistent interface structure for any table', async () => {
      await fc.assert(
        fc.asyncProperty(
          Arbitraries.queryFactoryOptions(),
          async (options) => {
            const factory = createQueryFactory<BaseEntity>(options);
            const wrapper = createWrapper();

            // Test that all generated hooks have the same interface structure
            const entitiesHook = renderHook(() => factory.useEntities(), { wrapper });
            const entityHook = renderHook(() => factory.useEntity('test-id'), { wrapper });
            const infiniteHook = renderHook(() => factory.useEntitiesInfinite(), { wrapper });
            const countHook = renderHook(() => factory.useEntitiesCount(), { wrapper });

            // Property: All hooks should have standard TanStack Query properties
            const standardProperties = ['data', 'isLoading', 'error', 'refetch', 'isError', 'isSuccess'];
            
            const entitiesHasStandardProps = standardProperties.every(prop => 
              entitiesHook.result.current.hasOwnProperty(prop)
            );
            
            const entityHasStandardProps = standardProperties.every(prop => 
              entityHook.result.current.hasOwnProperty(prop)
            );
            
            const countHasStandardProps = standardProperties.every(prop => 
              countHook.result.current.hasOwnProperty(prop)
            );

            // Property: Infinite hook should have additional pagination properties
            const infiniteProperties = ['data', 'isLoading', 'error', 'fetchNextPage', 'hasNextPage', 'isFetchingNextPage'];
            const infiniteHasProps = infiniteProperties.every(prop => 
              infiniteHook.result.current.hasOwnProperty(prop)
            );

            return entitiesHasStandardProps && entityHasStandardProps && countHasStandardProps && infiniteHasProps;
          }
        ),
        { numRuns: 50 }
      );
    });

    it('should handle filters consistently across all hook types', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.tuple(Arbitraries.queryFactoryOptions(), Arbitraries.queryFilters()),
          async ([options, filters]) => {
            const factory = createQueryFactory<BaseEntity>(options);
            const wrapper = createWrapper();

            // Property: All hooks should accept filters and maintain consistent behavior
            const entitiesWithFilters = renderHook(() => factory.useEntities({ filters }), { wrapper });
            const entityWithFilters = renderHook(() => factory.useEntity('test-id', { filters }), { wrapper });
            const infiniteWithFilters = renderHook(() => factory.useEntitiesInfinite({ filters }), { wrapper });
            const countWithFilters = renderHook(() => factory.useEntitiesCount({ filters }), { wrapper });

            // Property: All hooks should be in a valid initial state
            const allHooksValid = [
              entitiesWithFilters.result.current,
              entityWithFilters.result.current,
              infiniteWithFilters.result.current,
              countWithFilters.result.current
            ].every(hook => {
              return hook.error === null && 
                     typeof hook.isLoading === 'boolean' &&
                     typeof hook.isError === 'boolean' &&
                     typeof hook.isSuccess === 'boolean';
            });

            return allHooksValid;
          }
        ),
        { numRuns: 40 }
      );
    });

    it('should generate consistent pagination behavior across different entities', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.tuple(
            Arbitraries.tableName(),
            fc.integer({ min: 5, max: 50 })
          ),
          async ([tableName, pageSize]) => {
            const factory = createQueryFactory<BaseEntity>({
              tableName,
              defaultPageSize: pageSize
            });
            const wrapper = createWrapper();

            // Property: Infinite query should have consistent pagination interface
            const infiniteHook = renderHook(() => factory.useEntitiesInfinite({ pageSize }), { wrapper });
            const result = infiniteHook.result.current;

            // Property: Pagination properties should be consistent
            const hasPaginationProps = 
              result.hasOwnProperty('fetchNextPage') &&
              result.hasOwnProperty('hasNextPage') &&
              result.hasOwnProperty('isFetchingNextPage') &&
              result.hasOwnProperty('fetchPreviousPage') &&
              result.hasOwnProperty('hasPreviousPage');

            // Property: Pagination methods should be functions
            const paginationMethodsAreCallable = 
              typeof result.fetchNextPage === 'function' &&
              typeof result.fetchPreviousPage === 'function';

            // Property: Pagination states should be booleans
            const paginationStatesAreBoolean = 
              typeof result.hasNextPage === 'boolean' &&
              typeof result.hasPreviousPage === 'boolean' &&
              typeof result.isFetchingNextPage === 'boolean';

            return hasPaginationProps && paginationMethodsAreCallable && paginationStatesAreBoolean;
          }
        ),
        { numRuns: 30 }
      );
    });

    it('should maintain consistent error handling patterns across all hooks', async () => {
      await fc.assert(
        fc.asyncProperty(
          Arbitraries.queryFactoryOptions(),
          async (options) => {
            const factory = createQueryFactory<BaseEntity>(options);
            const wrapper = createWrapper();

            // Property: All hooks should have consistent error handling
            const hooks = [
              renderHook(() => factory.useEntities(), { wrapper }),
              renderHook(() => factory.useEntity('test-id'), { wrapper }),
              renderHook(() => factory.useEntitiesInfinite(), { wrapper }),
              renderHook(() => factory.useEntitiesCount(), { wrapper })
            ];

            // Property: All hooks should have consistent error state structure
            const allHaveConsistentErrorState = hooks.every(hook => {
              const result = hook.result.current;
              return result.hasOwnProperty('error') &&
                     result.hasOwnProperty('isError') &&
                     typeof result.isError === 'boolean' &&
                     (result.error === null || typeof result.error === 'object');
            });

            return allHaveConsistentErrorState;
          }
        ),
        { numRuns: 35 }
      );
    });

    it('should generate consistent cache keys for the same operations', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.tuple(Arbitraries.tableName(), Arbitraries.queryFilters()),
          async ([tableName, filters]) => {
            const factory1 = createQueryFactory<BaseEntity>({ tableName });
            const factory2 = createQueryFactory<BaseEntity>({ tableName });

            // Property: Same operations should generate identical cache keys
            const key1List = factory1.getQueryKey('list', filters);
            const key2List = factory2.getQueryKey('list', filters);
            
            const key1Single = factory1.getQueryKey('single', { ...filters, id: 'test-id' });
            const key2Single = factory2.getQueryKey('single', { ...filters, id: 'test-id' });
            
            const key1Infinite = factory1.getQueryKey('infinite', filters);
            const key2Infinite = factory2.getQueryKey('infinite', filters);
            
            const key1Count = factory1.getQueryKey('count', filters);
            const key2Count = factory2.getQueryKey('count', filters);

            // Property: Cache keys should be identical for same operations
            const listKeysMatch = JSON.stringify(key1List) === JSON.stringify(key2List);
            const singleKeysMatch = JSON.stringify(key1Single) === JSON.stringify(key2Single);
            const infiniteKeysMatch = JSON.stringify(key1Infinite) === JSON.stringify(key2Infinite);
            const countKeysMatch = JSON.stringify(key1Count) === JSON.stringify(key2Count);

            return listKeysMatch && singleKeysMatch && infiniteKeysMatch && countKeysMatch;
          }
        ),
        { numRuns: 25 }
      );
    });

    it('should maintain consistent factory configuration access', async () => {
      await fc.assert(
        fc.asyncProperty(
          Arbitraries.queryFactoryOptions(),
          async (options) => {
            const factory = createQueryFactory<BaseEntity>(options);

            // Property: Factory should provide consistent access to configuration
            const tableName = factory.getTableName();
            const config = factory.getConfig();

            // Property: Table name should match the provided option
            const tableNameMatches = tableName === options.tableName;

            // Property: Config should contain all provided options
            const configContainsOptions = 
              config.tableName === options.tableName &&
              (options.defaultFilters === undefined || 
               JSON.stringify(config.defaultFilters) === JSON.stringify(options.defaultFilters)) &&
              (options.realTimeSubscription === undefined || 
               config.realTimeSubscription === options.realTimeSubscription) &&
              (options.cacheTime === undefined || 
               config.cacheTime === options.cacheTime) &&
              (options.staleTime === undefined || 
               config.staleTime === options.staleTime) &&
              (options.defaultPageSize === undefined || 
               config.defaultPageSize === options.defaultPageSize);

            return tableNameMatches && configContainsOptions;
          }
        ),
        { numRuns: 40 }
      );
    });

    it('should provide consistent hook behavior regardless of entity type', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.array(Arbitraries.tableName(), { minLength: 2, maxLength: 5 }),
          async (tableNames) => {
            const wrapper = createWrapper();
            const factories = tableNames.map(tableName => 
              createQueryFactory<BaseEntity>({ tableName })
            );

            // Property: All factories should generate hooks with identical interfaces
            const allHooks = factories.map(factory => ({
              entities: renderHook(() => factory.useEntities(), { wrapper }),
              entity: renderHook(() => factory.useEntity('test-id'), { wrapper }),
              infinite: renderHook(() => factory.useEntitiesInfinite(), { wrapper }),
              count: renderHook(() => factory.useEntitiesCount(), { wrapper })
            }));

            // Property: All hooks should have the same property names
            const firstHookKeys = {
              entities: Object.keys(allHooks[0].entities.result.current).sort(),
              entity: Object.keys(allHooks[0].entity.result.current).sort(),
              infinite: Object.keys(allHooks[0].infinite.result.current).sort(),
              count: Object.keys(allHooks[0].count.result.current).sort()
            };

            const allHaveSameInterface = allHooks.every(hooks => {
              const entitiesKeys = Object.keys(hooks.entities.result.current).sort();
              const entityKeys = Object.keys(hooks.entity.result.current).sort();
              const infiniteKeys = Object.keys(hooks.infinite.result.current).sort();
              const countKeys = Object.keys(hooks.count.result.current).sort();

              return JSON.stringify(entitiesKeys) === JSON.stringify(firstHookKeys.entities) &&
                     JSON.stringify(entityKeys) === JSON.stringify(firstHookKeys.entity) &&
                     JSON.stringify(infiniteKeys) === JSON.stringify(firstHookKeys.infinite) &&
                     JSON.stringify(countKeys) === JSON.stringify(firstHookKeys.count);
            });

            return allHaveSameInterface;
          }
        ),
        { numRuns: 20 }
      );
    });

    it('should handle different filter types consistently', async () => {
      await fc.assert(
        fc.asyncProperty(
          fc.tuple(
            Arbitraries.tableName(),
            fc.record({
              stringFilter: fc.option(fc.string()),
              numberFilter: fc.option(fc.integer()),
              booleanFilter: fc.option(fc.boolean()),
              arrayFilter: fc.option(fc.array(fc.string(), { minLength: 1, maxLength: 3 }))
            })
          ),
          async ([tableName, filterValues]) => {
            const factory = createQueryFactory<BaseEntity>({ tableName });
            const wrapper = createWrapper();

            // Create filters with different value types
            const filters: QueryFilters = {
              where: {}
            };

            if (filterValues.stringFilter !== null) {
              filters.where!.stringField = filterValues.stringFilter;
            }
            if (filterValues.numberFilter !== null) {
              filters.where!.numberField = filterValues.numberFilter;
            }
            if (filterValues.booleanFilter !== null) {
              filters.where!.booleanField = filterValues.booleanFilter;
            }
            if (filterValues.arrayFilter !== null) {
              filters.where!.arrayField = filterValues.arrayFilter;
            }

            // Property: All hooks should handle different filter types without errors
            const entitiesHook = renderHook(() => factory.useEntities({ filters }), { wrapper });
            const entityHook = renderHook(() => factory.useEntity('test-id', { filters }), { wrapper });
            const infiniteHook = renderHook(() => factory.useEntitiesInfinite({ filters }), { wrapper });
            const countHook = renderHook(() => factory.useEntitiesCount({ filters }), { wrapper });

            // Property: All hooks should be in valid state (no immediate errors)
            const allHooksValid = [
              entitiesHook.result.current,
              entityHook.result.current,
              infiniteHook.result.current,
              countHook.result.current
            ].every(hook => {
              return typeof hook.isLoading === 'boolean' &&
                     typeof hook.isError === 'boolean' &&
                     (hook.error === null || typeof hook.error === 'object');
            });

            return allHooksValid;
          }
        ),
        { numRuns: 30 }
      );
    });
  });
});